// Parse the LLM JSON + attach the source URL
const llm = $input.first().json;
const content = llm.choices?.[0]?.message?.content || '{}';
let parsed = {};
try { parsed = JSON.parse(content); } catch (e) { parsed = { strategy_name: 'PARSE_ERROR', raw: content }; }
parsed.source = $('Inputs').first().json.video_url;
return [{ json: parsed }];
